select o.order_id,o.user_id,d.drug_name as drugName,o.time,o.price,o.quantity,o.total_price,o.order_status from orders o join drugs d on d.drug_id = o.drug_id
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select o.order_id,o.user_id,d.drug_name as drugName,o.time,o.price,o.quantity,o.total_price from orders o join drugs d on d.drug_id = o.drug_id where d.drug_name like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select o.order_id,o.user_id,d.drug_name as drugName,o.time,o.price,o.quantity,o.total_price from orders o join drugs d on d.drug_id = o.drug_id where o.order_id like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select o.order_id,o.user_id,d.drug_name as drugName,o.time,o.price,o.quantity,o.total_price from orders o join drugs d on d.drug_id = o.drug_id where o.user_id like CONCAT('%',#{value},'%')
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}

select o.order_id,o.user_id,d.drug_name as drugName,o.time,o.price,o.quantity,o.total_price,o.order_status as orderStatus,o.create_time as createTime,o.update_time as updateTime from orders o join drugs d on d.drug_id = o.drug_id
AND o.order_id LIKE CONCAT('%', #{oid}, '%')
AND o.order_status LIKE CONCAT('%', #{type}, '%')
AND o.user_id LIKE CONCAT('%', #{uid}, '%')
and o.create_time between #{startTime} and #{endTime}
ORDER BY ${orders}
ASC
DESC
limit #{size} offset #{offset}
